<template>
  <svg class="gallery-building-mark" :viewBox="viewBox" aria-hidden="true">
    <polygon v-for="(face,index) in faces" :key="index" :points="face.points" :class="[`material-${face.material}`,`plane-${face.plane}`, {'pavilion-roof':face.roof}]"/>
  </svg>
</template>
<script>
import { buildMuseumPavilion } from '../../utils/museumPavilionGeometry';
// Project the actual pavilion geometry into a small, render-free architectural model.
const boxes=[];
buildMuseumPavilion((w,h,d,material,x,y,z)=>boxes.push({w,h,d,material,x,y,z}),Object.fromEntries(['edge','floor','stone','paper','metal'].map(key=>[key,key])));
const project=([x,y,z])=>[x*.83-z*.56,(x*.56+z*.83)*.48-y*.88];
const faces=boxes.flatMap(b=>{
  const x=b.x-b.w/2,X=b.x+b.w/2,y=b.y-b.h/2,Y=b.y+b.h/2,z=b.z-b.d/2,Z=b.z+b.d/2;
  return [
    {plane:'side',vertices:[[X,y,z],[X,y,Z],[X,Y,Z],[X,Y,z]]},
    {plane:'front',vertices:[[x,y,Z],[X,y,Z],[X,Y,Z],[x,Y,Z]]},
    {plane:'top',vertices:[[x,Y,z],[X,Y,z],[X,Y,Z],[x,Y,Z]]},
  ].map(face=>({...face,material:b.material,roof:b.y>4.5&&b.h<.4,depth:face.vertices.reduce((v,p)=>v+p[0]*.56+p[2]*.83+p[1]*.3,0)/4,points:face.vertices.map(p=>project(p).join(',')).join(' ')}));
}).sort((a,b)=>a.depth-b.depth);
const points=faces.flatMap(f=>f.vertices.map(project));
const xs=points.map(p=>p[0]),ys=points.map(p=>p[1]);
const viewBox=[Math.min(...xs)-2,Math.min(...ys)-2,Math.max(...xs)-Math.min(...xs)+4,Math.max(...ys)-Math.min(...ys)+4].join(' ');
export default {name:'GalleryBuildingMark',data:()=>({faces,viewBox})};
</script>
<style scoped>
.gallery-building-mark{display:block;width:100%;height:100%;overflow:visible;filter:drop-shadow(0 8px 5px #252a2512)}
polygon{fill:#dcd9d0;stroke:#b1aea53d;stroke-width:.055;stroke-linejoin:round}
.plane-top{fill:#eeece5}.plane-side{fill:#c4c1b8}.material-edge{fill:#c9c6bd}.material-floor.plane-top{fill:#e5e2d9}.material-metal{fill:#706f66}
:global(body.dark-mode .gallery-building-mark .plane-top){fill:#bab9ad}:global(body.dark-mode .gallery-building-mark .plane-front){fill:#94968a}:global(body.dark-mode .gallery-building-mark .plane-side){fill:#72786b}:global(body.dark-mode .gallery-building-mark .material-edge){fill:#848a7d}:global(body.dark-mode .gallery-building-mark .material-metal){fill:#454b41}
</style>
