<template>
  <div class="exhibition-ticket" :class="{'is-open':opened,'is-departing':departing,'is-sample':sample}">
    <button ref="trigger" class="ticket-in-hand" data-press-intent="custom" type="button" :aria-label="`Exhibition ticket for ${view.title}, ${state.label.toLowerCase()}`" aria-haspopup="dialog" :aria-expanded="opened" @click="open">
      <Transition name="ticket-shuffle" mode="out-in">
        <div :key="view.id" class="ticket-resting"><ExhibitionTicketFace :title="view.title" :image="image" :date="date" :number="number" :state="state"/><span class="ticket-hint">{{ state.label }}</span></div>
      </Transition>
    </button>
    <Teleport to="body">
      <dialog ref="dialog" class="ticket-dialog" aria-label="Your exhibition ticket" @cancel.prevent.stop="close" @keydown.stop>
        <div ref="shade" class="ticket-shade" @click="close"></div>
        <div v-if="opened" ref="presentation" class="ticket-presentation" @click.self="close">
          <div ref="paper" class="ticket-perspective" @pointerdown="startTurn" @pointermove="moveTurn" @pointerup="endTurn" @pointercancel="cancelTurn" @lostpointercapture="cancelTurn" @wheel.prevent="wheelTurn">
            <div ref="turntable" class="ticket-turntable" @dragstart.prevent :class="{'is-dragging':dragging}" :style="{transform:`rotateY(${rotation+dragAngle}deg)`}">
              <ExhibitionTicketFace class="ticket-front" :title="view.title" :image="image" :date="date" :number="number" :state="state" expanded :inert="flipped" :aria-hidden="flipped"/>
              <ExhibitionTicketFace class="ticket-back" :title="view.title" :image="image" :date="date" :number="number" :summary="summary" :state="state" expanded reverse :inert="!flipped" :aria-hidden="!flipped"/>
            </div>
            <button v-if="!flipped && !turnLearned" class="ticket-turn-hint" type="button" aria-label="Turn ticket over by its edge" @pointerdown.stop @click.stop="flip(-1)"><svg viewBox="0 0 24 24" aria-hidden="true"><path d="M20 12H4m5-5-5 5 5 5"/></svg><span>Turn over</span></button>
          </div>
          <div ref="actions" class="ticket-actions" @click.self="close">
            <button class="ticket-action ticket-flip-action" type="button" :aria-label="flipped?'Show front of ticket':'Turn ticket over'" @click="flip()"><svg viewBox="0 0 24 24" aria-hidden="true"><path d="M5 8V4m0 4h4M5 8a8 8 0 1 1-1 8"/></svg><span>{{flipped?'Front':'Reverse'}}</span></button>
            <button v-if="!sample" class="ticket-action" type="button" @click="enter">To the entrance<svg viewBox="0 0 20 20" aria-hidden="true"><path d="M4 10h12m-5-5 5 5-5 5"/></svg></button>
            <button ref="close" class="ticket-action ticket-put-away" type="button" @click="close"><svg viewBox="0 0 20 20" aria-hidden="true"><path d="m5 5 10 10M15 5 5 15"/></svg>{{sample?'Close':'Put away'}}</button>
          </div>
        </div>
      </dialog>
    </Teleport>
  </div>
</template>
<script>
import ExhibitionTicketFace from './ExhibitionTicketFace.vue';
import { getSharedView } from '../../utils/viewShareSite';
import { museumSession, updateMuseumSession } from '../../utils/viewMuseumSession';
import { exhibitionTicketState, exhibitionTicketNumber } from '../../utils/exhibitionTicket';
const snapshots=new Map();
export default {
  components:{ExhibitionTicketFace},
  props:{view:{type:Object,required:true},departing:Boolean,sample:Boolean},
  emits:['entrance'],
  data:()=>({opened:false,session:{},snapshot:null,flipped:false,rotation:0,dragging:false,dragAngle:0,turnLearned:false}),
  computed:{
    number(){return exhibitionTicketNumber(this.view.id);},
    state(){return exhibitionTicketState(this.view.id,this.session);},
    summary(){return this.view.dek||this.snapshot?.view?.dek||'';},
    date(){const value=this.view.created_at||this.snapshot?.created_at;if(!value)return '';const date=new Date(value);return Number.isNaN(date.getTime())?'':new Intl.DateTimeFormat('en-GB',{day:'numeric',month:'short',year:'numeric'}).format(date);},
    image(){const art=this.view.illustration||this.snapshot?.view?.illustration;return typeof art==='string'?art:art?.src||'';},
  },
  watch:{'view.id':{immediate:true,handler(){this.snapshot=null;this.sync();this.loadDetails();}}},
  mounted(){window.addEventListener('museum-visit-updated',this.sync);window.addEventListener('blur',this.cancelTurn);},
  beforeUnmount(){this._destroyed=true;window.removeEventListener('blur',this.cancelTurn);window.removeEventListener('museum-visit-updated',this.sync);this._animations?.forEach(a=>a.cancel());this.$refs.dialog?.close();},
  methods:{
    learnTurn(){this.turnLearned=true;updateMuseumSession({ticketTurnLearned:true});},
    setFace(){this.flipped=Math.abs(Math.round(this.rotation/180))%2===1;},
    currentRotation(){
      const matrix=new DOMMatrixReadOnly(getComputedStyle(this.$refs.turntable).transform);
      const angle=Math.atan2(-matrix.m13,matrix.m11)*180/Math.PI;
      return angle+Math.round((this.rotation-angle)/360)*360;
    },
    flip(direction=1){if(this._closing)return;this.rotation+=direction*180;this.setFace();this.dragAngle=0;this.learnTurn();},
    startTurn(event){
      if(event.button!==0||this._closing||event.target.closest('button'))return;
      this.rotation=this.currentRotation();this.dragAngle=0;this.dragging=true;
      this._drag={x:event.clientX,y:event.clientY,id:event.pointerId,width:this.$refs.paper.offsetWidth};
      this.$refs.paper.setPointerCapture(event.pointerId);
    },
    moveTurn(event){
      if(!this.dragging||event.pointerId!==this._drag?.id)return;
      if(event.buttons===0){this.endTurn(event);return;}
      this.dragAngle=(event.clientX-this._drag.x)/this._drag.width*240;
    },
    endTurn(event){
      if(!this.dragging||event.pointerId!==this._drag?.id)return;
      const dx=event.clientX-this._drag.x,dy=event.clientY-this._drag.y;
      const angle=this.rotation+this.dragAngle;
      this.dragging=false;this.dragAngle=0;
      this.rotation=Math.abs(dx)<6&&Math.abs(dy)<6?Math.round(angle/180)*180+180:Math.round(angle/180)*180;
      this.setFace();if(Math.abs(dx)>12||Math.abs(dy)<6)this.learnTurn();
      const id=this._drag.id;this._drag=null;if(this.$refs.paper.hasPointerCapture(id))this.$refs.paper.releasePointerCapture(id);
    },
    cancelTurn(){
      if(this.dragging){this.rotation=Math.round((this.rotation+this.dragAngle)/180)*180;this.setFace();}
      this.dragging=false;this.dragAngle=0;
      const id=this._drag?.id;this._drag=null;if(id!==undefined&&this.$refs.paper?.hasPointerCapture(id))this.$refs.paper.releasePointerCapture(id);
    },
    wheelTurn(event){
      if(this._closing||this.dragging||event.ctrlKey)return;
      const now=performance.now();if(now-(this._wheelAt||0)>180)this._wheelDistance=0;
      this._wheelAt=now;if(now<(this._wheelUntil||0))return;
      this._wheelDistance=(this._wheelDistance||0)+(Math.abs(event.deltaX)>Math.abs(event.deltaY)?event.deltaX:event.deltaY);
      if(Math.abs(this._wheelDistance)>45){this.flip(this._wheelDistance>0?-1:1);this._wheelDistance=0;this._wheelUntil=now+650;}
    },
    async loadDetails(){
      if(this.view.dek)return;
      const id=this.view.id;
      if(!snapshots.has(id))snapshots.set(id,getSharedView(id).catch(error=>{snapshots.delete(id);throw error;}));
      try{const snapshot=await snapshots.get(id);if(!this._destroyed&&this.view.id===id)this.snapshot=snapshot;}catch{/* A later opening retries an unavailable summary. */}
    },
    sync(){this.session=museumSession();this.turnLearned=Boolean(this.session.ticketTurnLearned);},
    origin(){
      const target=this.$refs.trigger.querySelector('.ticket-face'),paper=this.$refs.paper;
      if(!target)return 'scale(.25)';
      const a=target.getBoundingClientRect(),b=this.$refs.presentation.getBoundingClientRect();
      const matrix=new DOMMatrixReadOnly(getComputedStyle(this.$refs.trigger.querySelector('.ticket-resting')).transform);
      const rotation=Math.atan2(matrix.b,matrix.a)*180/Math.PI;
      const scale=Math.hypot(matrix.a,matrix.b);
      return `translate(${a.left+a.width/2-b.left-b.width/2}px,${a.top+a.height/2-b.top-paper.offsetHeight/2}px) rotate(${rotation}deg) scale(${target.offsetWidth*scale/paper.offsetWidth},${target.offsetHeight*scale/paper.offsetHeight})`;
    },
    async open(){
      if(this.opened)return;
      this.sync();this.loadDetails();this.flipped=false;this.rotation=0;this.dragAngle=0;this.opened=true;
      await this.$nextTick();if(this._destroyed)return;
      this.$refs.dialog.showModal();this.$refs.close.focus({preventScroll:true});
      this._motion=!matchMedia('(prefers-reduced-motion: reduce)').matches;
      this._origin=this.origin();
      if(this._motion)this._animations=[
        this.$refs.paper.animate([{transform:this._origin},{transform:'none'}],{duration:440,easing:'cubic-bezier(.22,1,.36,1)'}),
        this.$refs.shade.animate([{opacity:0,backdropFilter:'blur(0px)'},{opacity:1,backdropFilter:'blur(6px)'}],{duration:400,easing:'ease-out'}),
        this.$refs.actions.animate([{opacity:0},{opacity:1}],{duration:400,easing:'ease-out'}),
      ];
    },
    async close(){
      if(!this.opened||this._closing)return;
      this._closing=true;
      const current=getComputedStyle(this.$refs.paper).transform;
      const turn=getComputedStyle(this.$refs.turntable).transform;
      this.cancelTurn();
      this._animations?.forEach(a=>a.cancel());
      this._origin=this.origin();
      this.rotation=Math.round(this.rotation/360)*360;this.flipped=false;
      if(this._motion){
        this._animations=[
          this.$refs.paper.animate([{transform:current},{transform:this._origin}],{duration:420,easing:'cubic-bezier(.4,0,.2,1)',fill:'forwards'}),
          this.$refs.turntable.animate([{transform:turn},{transform:`rotateY(${this.rotation}deg)`}],{duration:360,easing:'cubic-bezier(.22,1,.36,1)',fill:'forwards'}),
          this.$refs.shade.animate([{opacity:1,backdropFilter:'blur(6px)'},{opacity:0,backdropFilter:'blur(0px)'}],{duration:420,easing:'ease-in-out',fill:'forwards'}),
          this.$refs.actions.animate([{opacity:1},{opacity:0}],{duration:160,fill:'forwards'}),
        ];
        await Promise.all(this._animations.map(a=>a.finished.catch(()=>{})));
      }
      if(this._destroyed)return;
      this.opened=false;await this.$nextTick();this.$refs.dialog.close();this._closing=false;this._animations?.forEach(a=>a.cancel());
      this.$refs.trigger.focus({preventScroll:true});
    },
    async enter(){await this.close();if(!this._destroyed)this.$emit('entrance');},
  },
};
</script>
<style scoped>
.exhibition-ticket{position:absolute;z-index:8;right:32px;bottom:104px;width:176px;pointer-events:none;transition:opacity 320ms ease;}
.exhibition-ticket.is-departing{opacity:0;pointer-events:none;}
.ticket-in-hand{display:block;width:100%;padding:12px 0;border:0;background:none;cursor:var(--site-interactive-cursor,pointer);color:var(--ex-muted,#797266);text-align:center;pointer-events:auto;}
.is-departing .ticket-in-hand{pointer-events:none;}
.ticket-resting{transform:rotate(-7deg);transform-origin:50% 50%;transition:transform 240ms cubic-bezier(.22,1,.36,1),filter 240ms ease;filter:drop-shadow(0 5px 7px #151d192c);pointer-events:none;}
.ticket-in-hand:focus-visible{outline:2px solid var(--ex-accent,#8c6d3e);outline-offset:8px;}
.ticket-hint{display:block;font:10px/1.4 'Quattrocento Sans',sans-serif;letter-spacing:.035em;margin-top:9px;opacity:1;transform:translateY(0);transition:opacity 240ms ease,transform 280ms cubic-bezier(.22,1,.36,1);}
.is-open .ticket-resting>.ticket-face{visibility:hidden;}
.is-open .ticket-hint{opacity:0;transform:translateY(5px);}
@media(hover:hover){.ticket-in-hand:hover .ticket-resting{transform:translateY(-5px) rotate(-4deg) scale(1.025);filter:drop-shadow(0 12px 12px #151d1942);}.is-sample .ticket-in-hand:hover .ticket-resting{transform:translateY(-5px) rotate(-2deg) scale(1.025);}}
.ticket-dialog{position:fixed;inset:0;width:100%;height:100%;max-width:none;max-height:none;padding:0;margin:0;border:0;background:transparent;overflow:auto;}
.ticket-dialog::backdrop{background:transparent;}
.ticket-shade{position:fixed;inset:0;background:#1017136b;backdrop-filter:blur(6px);}
.ticket-presentation{position:relative;width:min(700px,calc(100vw - 40px));margin: max(24px, calc((100dvh - 580px)/2)) auto 32px;}
.ticket-perspective:has(.is-dragging){cursor:var(--site-black-grabbing-cursor,grabbing);}
.ticket-perspective{touch-action:none;cursor:var(--site-black-grab-cursor,grab);perspective:1400px;position:relative;filter:drop-shadow(0 24px 36px #080e1238);}
.ticket-turntable{display:grid;pointer-events:none;transform-style:preserve-3d;transition:transform 480ms cubic-bezier(.22,1,.36,1);touch-action:pan-y;cursor:var(--site-black-grab-cursor,grab);user-select:none;}
.ticket-turntable.is-dragging{transition:none;cursor:var(--site-black-grabbing-cursor,grabbing);}
.ticket-turntable>.ticket-face{grid-area:1/1;min-height:0;backface-visibility:hidden;-webkit-backface-visibility:hidden;}
.ticket-back{position:absolute;inset:0;height:100%;transform:rotateY(180deg);}
.ticket-turn-hint{position:absolute;right:2%;top:68%;display:flex;flex-direction:column;align-items:center;gap:5px;padding:8px 2px;border:0;background:none;color:#747562;font:10px/1.2 "Quattrocento Sans",sans-serif;cursor:var(--site-interactive-cursor,pointer);}.ticket-turn-hint svg{width:23px;height:23px;stroke:currentColor;stroke-width:1;fill:none;transition:transform 180ms ease;}.ticket-turn-hint:hover svg{transform:translateX(-3px);}
.ticket-actions{user-select:none;-webkit-user-select:none;display:flex;justify-content:center;align-items:center;gap:26px;padding:22px 0 4px;}
.ticket-action{display:flex;align-items:center;gap:6px;margin:0;padding:8px 0;border:0;background:none;color:#eeeadecf;font:12px/1.2 'Quattrocento Sans',sans-serif;cursor:var(--site-interactive-cursor,pointer);transition:color 160ms ease;}
.ticket-flip-action{display:grid;grid-template-columns:16px 50px;width:72px;justify-content:start;flex:none;}
.ticket-flip-action span{text-align:left;}
.ticket-put-away{color:#eeeade9e;}
.ticket-action svg{width:16px;height:16px;fill:none;stroke:currentColor;stroke-width:1.2;}
.ticket-action:hover{color:#fffaf0;}.ticket-action:focus-visible{outline:1px solid #eeeade;outline-offset:4px;}
.ticket-shuffle-enter-active,.ticket-shuffle-leave-active{transition:transform 220ms cubic-bezier(.22,1,.36,1),opacity 180ms ease;}
.ticket-shuffle-enter-from{transform:translateX(65px) rotate(5deg);opacity:0;}.ticket-shuffle-leave-to{transform:translateX(-50px) rotate(-16deg);opacity:0;}
@media(max-width:767px) and (orientation:portrait){.exhibition-ticket{width:118px;right:20px;top:148px;bottom:auto;}.ticket-hint{font-size:9px;margin-top:6px;}.ticket-presentation{width:calc(100vw - 32px);margin-top:max(28px,calc((100dvh - 490px)/2));}.ticket-action{min-height:44px;font-size:11px;}.ticket-actions{gap:18px;}}
@media(max-height:600px) and (orientation:landscape){.exhibition-ticket{width:128px;bottom:80px;}.ticket-presentation{width:min(620px,calc((100dvh - 100px)*1.55));margin-top:18px;}}
.exhibition-ticket.is-sample{position:relative;inset:auto;width:min(100%,370px);margin:auto;z-index:0;}
.is-sample .ticket-resting{transform:rotate(-4deg);}
@media(prefers-reduced-motion:reduce){.exhibition-ticket,.ticket-resting,.ticket-hint,.ticket-action,.ticket-turntable,.ticket-shuffle-enter-active,.ticket-shuffle-leave-active{transition:none;}.ticket-shade{backdrop-filter:none;}}
</style>
